function pedacos(texto, tam = 1900) {
  const s = String(texto || '');
  const out = [];
  for (let i = 0; i < s.length && out.length < 50; i += tam) out.push({ text: { content: s.slice(i, i + tam) } });
  return out.length ? out : [];
}
