const campanha = !!ctx.empresaId;
if (nivel === 1 && (!campanha || !NIVEL1_OK.includes(intencao))) nivel = 2;
if (conf < 0.8 && nivel < 3) nivel += 1;
if (['quente e sensível', 'fora da campanha', 'robô'].includes(intencao)) nivel = 3;
