function primeiroNome(nomeCrm) {
  const p = String(nomeCrm || '').replace(/\s*\(.*\)\s*$/, '').trim().split(/\s+/)[0] || '';
  if (!/^[A-Za-zÀ-ÿ][A-Za-zÀ-ÿ'-]{1,}$/.test(p)) return '';
