function formataTel(d) {
  const s = soDigitos(d);
  if (s.length === 12 || s.length === 13) {
    const loc = s.slice(4);
    return `+${s.slice(0, 2)} ${s.slice(2, 4)} ${loc.slice(0, loc.length - 4)}-${loc.slice(-4)}`;
  }
  return s ? `+${s}` : '';
}

